// cruise_tests.go: the tests of a hosted Cruise draft, generated by the
// service from the aim you describe.
//
//	ks cruise tests estimate DRAFT   what a generation would use, before asking for one
//	ks cruise tests generate DRAFT   ask for the tests (--yes accepts the estimate)
//	ks cruise tests show DRAFT       the state, each test's sentence and how it ran, what was dropped
//	ks cruise tests review DRAFT     every file in full, the set digest computed here, then the review
//	ks cruise tests discard DRAFT    drop the generated tests
//
// The service writes the tests, then runs them twice on your files, as they
// are now, in the verifier's sandbox: every test the job must turn from
// failing to passing failed both times; a test that passes today is dropped
// from what the job must fix and listed; a test that does not repeat refuses
// the whole set. The review is read-only. This client does not take the
// service's word for the set: the digest it reviews is computed here from
// the files it shows, each file's sha256 from its own bytes.
package main

import (
	"bufio"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"os"
	"sort"
	"strings"
)

// testsView is a draft's tests as the service returns them.
type testsView struct {
	DraftID  string `json:"draft_id"`
	Revision int64  `json:"revision"`
	Source   string `json:"source"`
	State    string `json:"state"`
	Stage    string `json:"stage"`
	Aim      *struct {
		Build       string `json:"build"`
		Acceptance  string `json:"acceptance"`
		Constraints string `json:"constraints"`
	} `json:"aim"`
	Model    *rung `json:"model"`
	KeyRoute *struct {
		Source   string `json:"source"`
		Provider string `json:"provider"`
		KeyID    string `json:"key_id"`
	} `json:"key_route"`
	Generation *struct {
		ID      string `json:"id"`
		Number  int64  `json:"number"`
		Count   int64  `json:"count"`
		Limit   int64  `json:"limit"`
		Session struct {
			ID        string `json:"id"`
			State     string `json:"state"`
			DeletedAt string `json:"deleted_at"`
		} `json:"session"`
	} `json:"generation"`
	Files []struct {
		Path    string `json:"path"`
		SHA256  string `json:"sha256"`
		Bytes   int64  `json:"bytes"`
		Content string `json:"content"`
	} `json:"files"`
	Tests []struct {
		ID         string   `json:"id"`
		File       string   `json:"file"`
		Name       string   `json:"name"`
		Sentence   string   `json:"sentence"`
		Acceptance string   `json:"acceptance"`
		Red        []string `json:"red"`
		Status     string   `json:"status"`
		Witnessed  *bool    `json:"witnessed"`
	} `json:"tests"`
	Dropped []struct {
		ID  string `json:"id"`
		Why string `json:"why"`
	} `json:"dropped"`
	Untested       []string        `json:"untested"`
	SetDigest      string          `json:"set_digest"`
	ReviewedDigest string          `json:"reviewed_digest"`
	Usage          json.RawMessage `json:"usage"`
	Cost           json.RawMessage `json:"cost"`
	Refusal        *struct {
		Code    string `json:"code"`
		Message string `json:"message"`
	} `json:"refusal"`
}

func testsRoute(id string) string { return draftsRoute + "/" + url.PathEscape(id) + "/tests" }

func fetchTests(cr hostedCreds, id string) (*testsView, json.RawMessage) {
	var env draftEnvelope
	if err := hostedCall(cr, "GET", testsRoute(id), nil, &env); err != nil {
		die(err)
	}
	var v testsView
	if err := json.Unmarshal(env.Data, &v); err != nil || v.DraftID == "" {
		die(fmt.Errorf("the control plane answered with tests this client could not read"))
	}
	return &v, env.Data
}

// setDigest is the digest of a set of files: sha256 over the files in path
// order, each its path, a zero byte, its sha256 in hex and a newline.
func setDigest(files map[string]string) string {
	paths := make([]string, 0, len(files))
	for p := range files {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	h := sha256.New()
	for _, p := range paths {
		h.Write([]byte(p + "\x00" + files[p] + "\n"))
	}
	return hex.EncodeToString(h.Sum(nil))
}

// shownSet computes the set digest here from the files the service showed,
// each file's sha256 from its own bytes; a file whose bytes are not the
// sha256 shown beside it is refused.
func shownSet(v *testsView) string {
	files := map[string]string{}
	for _, f := range v.Files {
		sum := sha256.Sum256([]byte(f.Content))
		got := hex.EncodeToString(sum[:])
		if got != strings.ToLower(f.SHA256) {
			fail(integrity("tests_file_mismatch", fmt.Sprintf("%s's bytes hash to %s here, and the service states %s; nothing was reviewed", f.Path, short(got), short(f.SHA256))))
		}
		files[f.Path] = got
	}
	return setDigest(files)
}

func printTests(w io.Writer, v *testsView, withFiles bool) {
	fmt.Fprintf(w, "tests of draft %s  %s  (source %s)\n", v.DraftID, strings.ToUpper(v.State), v.Source)
	if v.Aim != nil {
		fmt.Fprintf(w, "  aim          %s\n", visible(sanitize(v.Aim.Build)))
		fmt.Fprintf(w, "  done when    %s\n", visible(sanitize(v.Aim.Acceptance)))
		if v.Aim.Constraints != "" {
			fmt.Fprintf(w, "  constraints  %s\n", visible(sanitize(v.Aim.Constraints)))
		}
	}
	if v.Model != nil && v.KeyRoute != nil {
		whose := "your own " + v.KeyRoute.Provider + " key"
		if v.KeyRoute.Source == "house_generation" {
			whose = "KeepState's key, free"
		}
		fmt.Fprintf(w, "  written by   %s on %s\n", sanitize(v.Model.Model), whose)
	}
	if v.Stage != "" {
		fmt.Fprintf(w, "  stage        %s\n", sanitize(v.Stage))
	}
	if v.Generation != nil {
		fmt.Fprintf(w, "  generation   %s, %d of %d for this draft", v.Generation.ID, v.Generation.Count, v.Generation.Limit)
		if v.Generation.Session.State == "deleted" {
			fmt.Fprintf(w, "; its machine was deleted at %s", sanitize(v.Generation.Session.DeletedAt))
		}
		fmt.Fprintln(w)
	}
	if v.Refusal != nil {
		fmt.Fprintf(w, "  refused      %s: %s\n", sanitize(v.Refusal.Code), visible(sanitize(v.Refusal.Message)))
	}
	for _, t := range v.Tests {
		how := "fails now, twice"
		switch t.Status {
		case "passes_today":
			how = "passes today: dropped from what the job must fix"
		case "flaky":
			how = "did not give the same result twice"
		case "absent":
			how = "did not run in both runs"
		}
		if t.Status == "red" && t.Witnessed != nil {
			if *t.Witnessed {
				how += "; a sample solution passes it"
			} else {
				how += "; a sample solution does not pass it"
			}
		}
		fmt.Fprintf(w, "  test         %s\n               %s (%s)\n", sanitize(t.ID), visible(sanitize(t.Sentence)), how)
	}
	for _, u := range v.Untested {
		fmt.Fprintf(w, "  untested     %s\n", visible(sanitize(u)))
	}
	if string(v.Usage) != "" && string(v.Usage) != "null" {
		fmt.Fprintf(w, "  usage        %s\n", sanitize(strings.Trim(string(v.Usage), `"`)))
	}
	if withFiles {
		for _, f := range v.Files {
			fmt.Fprintf(w, "\n----- %s (%d bytes, sha256 %s) -----\n", sanitize(f.Path), f.Bytes, f.SHA256)
			fmt.Fprint(w, visible(f.Content))
			if !strings.HasSuffix(f.Content, "\n") {
				fmt.Fprintln(w)
			}
		}
		if len(v.Files) > 0 {
			fmt.Fprintln(w)
		}
	}
	if v.SetDigest != "" {
		fmt.Fprintf(w, "  set          %s (the service)\n", v.SetDigest)
	}
	if v.ReviewedDigest != "" {
		fmt.Fprintf(w, "  reviewed     %s\n", v.ReviewedDigest)
	}
}

func hostedCruiseTestsEstimate(cr hostedCreds, inv *Invocation) {
	var env draftEnvelope
	if err := hostedMutate(cr, "POST", testsRoute(inv.Arg(0))+"/estimate", map[string]any{}, &env); err != nil {
		die(err)
	}
	emit(env.Data, func() { printEstimate(os.Stdout, env.Data) })
}

func printEstimate(w io.Writer, raw json.RawMessage) {
	var e struct {
		Runner   string `json:"runner"`
		Model    rung   `json:"model"`
		KeyRoute struct {
			Source, Provider string
		} `json:"key_route"`
		Tokens struct {
			In    int64 `json:"input_per_call"`
			Out   int64 `json:"output_per_call_at_most"`
			Calls int64 `json:"calls_at_most"`
			Total int64 `json:"budget"`
		} `json:"tokens"`
		Minutes int64  `json:"machine_minutes_at_most"`
		Dollars any    `json:"dollars"`
		Note    string `json:"note"`
	}
	_ = json.Unmarshal(raw, &e)
	whose := "your own " + e.KeyRoute.Provider + " key"
	if e.KeyRoute.Source == "house_generation" {
		whose = "KeepState's key, free"
	}
	fmt.Fprintf(w, "tests for %s, written by %s on %s\n", sanitize(e.Runner), sanitize(e.Model.Model), whose)
	fmt.Fprintf(w, "  tokens       about %s in per call, at most %s out per call, at most %d calls, %s in all\n", commas(e.Tokens.In), commas(e.Tokens.Out), e.Tokens.Calls, commas(e.Tokens.Total))
	fmt.Fprintf(w, "  machine      at most %d minutes\n", e.Minutes)
	fmt.Fprintf(w, "  dollars      %s\n", sanitize(fmt.Sprint(e.Dollars)))
	if e.Note != "" {
		fmt.Fprintf(w, "  note         %s\n", visible(sanitize(e.Note)))
	}
}

func hostedCruiseTestsGenerate(cr hostedCreds, inv *Invocation) {
	id := inv.Arg(0)
	var est draftEnvelope
	if err := hostedMutate(cr, "POST", testsRoute(id)+"/estimate", map[string]any{}, &est); err != nil {
		die(err)
	}
	printEstimate(os.Stderr, est.Data)
	if !inv.Bool("yes") {
		if out.noInput || !stdinIsTerminal() {
			fail(&cliError{Code: exitUsage, Kind: "confirmation_required", Message: "a generation uses a model on the key shown; confirm it with --yes. Nothing was asked for",
				NextAction: "ks cruise tests generate " + id + " --yes"})
		}
		fmt.Fprint(os.Stderr, "ask for these tests? [y/N] ")
		line, _ := bufio.NewReader(os.Stdin).ReadString('\n')
		if a := strings.ToLower(strings.TrimSpace(line)); a != "y" && a != "yes" {
			fail(&cliError{Code: exitUsage, Kind: "confirmation_declined", Message: "the generation was not confirmed; nothing was asked for"})
		}
	}
	v, _ := fetchDraft(cr, id)
	var env draftEnvelope
	if err := hostedMutate(cr, "POST", testsRoute(id)+"/generate", map[string]any{"expected_revision": v.Revision}, &env); err != nil {
		die(err)
	}
	var tv testsView
	_ = json.Unmarshal(env.Data, &tv)
	emit(env.Data, func() {
		printTests(os.Stdout, &tv, false)
		fmt.Printf("next: ks cruise tests show %s (the tests are written, then run twice on your files)\n", id)
	})
}

func hostedCruiseTestsShow(cr hostedCreds, inv *Invocation) {
	v, raw := fetchTests(cr, inv.Arg(0))
	emit(raw, func() {
		printTests(os.Stdout, v, inv.Bool("files"))
		switch v.State {
		case "generated":
			fmt.Printf("next: ks cruise tests review %s (every file in full, then the set digest computed here)\n", v.DraftID)
		case "reviewed":
			fmt.Printf("next: ks cruise draft approve %s\n", v.DraftID)
		case "awaiting_aim", "refused":
			fmt.Printf("next: ks cruise tests generate %s\n", v.DraftID)
		}
	})
}

func hostedCruiseTestsReview(cr hostedCreds, inv *Invocation) {
	v, _ := fetchTests(cr, inv.Arg(0))
	if v.State != "generated" && v.State != "reviewed" {
		fail(&cliError{Code: exitConflict, Kind: "tests_state", Message: fmt.Sprintf("the tests of draft %s are %s; there is no set to review", v.DraftID, v.State),
			NextAction: "ks cruise tests show " + v.DraftID})
	}
	computed := shownSet(v)
	if v.SetDigest != "" && computed != strings.ToLower(v.SetDigest) {
		fail(integrity("set_digest_mismatch", fmt.Sprintf("the files shown digest to %s here, and the service states %s; nothing was reviewed", short(computed), short(v.SetDigest))))
	}
	// every file in full, before anything is sent (stderr, so --json stays one document)
	printTests(os.Stderr, v, true)
	fmt.Fprintf(os.Stderr, "  set          %s (computed here from the files shown)\n", computed)
	given := strings.ToLower(strings.TrimSpace(inv.Str("confirm")))
	matches := func(s string) bool {
		s = strings.ToLower(strings.TrimSpace(s))
		return s == computed || (len(s) == 12 && s == short(computed))
	}
	switch {
	case given != "":
		if !matches(given) {
			fail(&cliError{Code: exitUsage, Kind: "confirmation_mismatch", Message: fmt.Sprintf("--confirm %q is not the digest of the files shown (%s); nothing was reviewed", given, short(computed))})
		}
	case out.noInput || !stdinIsTerminal():
		fail(&cliError{Code: exitUsage, Kind: "confirmation_required", Message: "a review is confirmed by the set's digest and none was given; nothing was reviewed",
			NextAction: fmt.Sprintf("ks cruise tests review %s --confirm %s", v.DraftID, short(computed))})
	default:
		fmt.Fprintf(os.Stderr, "type the set digest (%s) to say you read these tests, or anything else to stop: ", short(computed))
		line, _ := bufio.NewReader(os.Stdin).ReadString('\n')
		if !matches(line) {
			fail(&cliError{Code: exitUsage, Kind: "confirmation_declined", Message: "the set digest was not confirmed; nothing was reviewed"})
		}
	}
	var env draftEnvelope
	if err := hostedMutate(cr, "POST", testsRoute(v.DraftID)+"/review", map[string]any{"set_digest": computed}, &env); err != nil {
		die(err)
	}
	emit(env.Data, func() {
		fmt.Printf("reviewed the generated tests of %s: set %s\n", v.DraftID, short(computed))
		fmt.Printf("next: ks cruise draft approve %s\n", v.DraftID)
	})
}

func hostedCruiseTestsDiscard(cr hostedCreds, inv *Invocation) {
	var env draftEnvelope
	if err := hostedMutate(cr, "DELETE", testsRoute(inv.Arg(0)), nil, &env); err != nil {
		die(err)
	}
	emit(env.Data, func() {
		fmt.Printf("the generated tests of %s are discarded; ask again with ks cruise tests generate %s\n", inv.Arg(0), inv.Arg(0))
	})
}

// generatedSetChecks are --verify's checks of a draft whose tests were
// generated: every generated file is in the archive with the sha256 the
// manifest names, the set digest is theirs, each is pinned, and nothing else
// is in their folder.
func generatedSetChecks(ver map[string]any, bySHA map[string]string, add func(name, got, want string)) int {
	g, ok := ver["generated"].(map[string]any)
	if !ok {
		return 0
	}
	files, _ := g["files"].([]any)
	pinned := map[string]bool{}
	if pp, ok := ver["prohibited_paths"].([]any); ok {
		for _, x := range pp {
			if s, _ := x.(string); s != "" {
				pinned[s] = true
			}
		}
	}
	named := map[string]string{}
	bad, loose := 0, 0
	for _, f := range files {
		fm, _ := f.(map[string]any)
		p, _ := fm["path"].(string)
		h, _ := fm["sha256"].(string)
		named[p] = h
		if bySHA[p] != h {
			bad++
		}
		if !pinned[p] {
			loose++
		}
	}
	add("every generated file is in the archive with the sha256 the manifest names", fmt.Sprintf("%d of %d differ", bad, len(files)), fmt.Sprintf("0 of %d differ", len(files)))
	add("every generated file is pinned (verifier.prohibited_paths)", fmt.Sprintf("%d of %d not pinned", loose, len(files)), fmt.Sprintf("0 of %d not pinned", len(files)))
	fromArchive := map[string]string{}
	for p := range named {
		fromArchive[p] = bySHA[p]
	}
	add("the generated set digest is the manifest's verifier.generated.set_digest", setDigest(fromArchive), fmt.Sprint(g["set_digest"]))
	extra := 0
	root := ""
	for p := range named {
		if i := strings.LastIndex(p, "/"); i > 0 {
			root = p[:i+1]
		}
	}
	for p := range bySHA {
		if root != "" && strings.HasPrefix(p, root) && named[p] == "" {
			extra++
		}
	}
	add("the archive holds no other file in the generated tests' folder", fmt.Sprintf("%d other file(s)", extra), "0 other file(s)")
	return len(files)
}
